<?php
require_once __DIR__ . '/includes/functions.php';
$user=require_login(); require_permission($user,'triage.manage');
$pageTitle='IGD / Triase'; $pdo=db();
$pdo->exec("CREATE TABLE IF NOT EXISTS nursing_followups (id INT AUTO_INCREMENT PRIMARY KEY, registration_id INT NOT NULL, nurse_employee_id INT NOT NULL, action_note TEXT NOT NULL, performed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(registration_id) REFERENCES registrations(id), FOREIGN KEY(nurse_employee_id) REFERENCES employees(id)) ENGINE=InnoDB");
[$scope,$scopeParams]=patient_scope($user,'active');
$igdGuard="EXISTS (SELECT 1 FROM units iu WHERE iu.id=r.unit_id AND iu.unit_type='IGD')";
if (is_admin($user)) { $scope=$igdGuard; $scopeParams=[]; }
$regStmt=$pdo->prepare("SELECT r.id,r.registration_no,p.full_name,p.medical_record_no FROM registrations r JOIN patients p ON p.id=r.patient_id WHERE ($scope) AND ($igdGuard) ORDER BY r.id DESC LIMIT 100");
$regStmt->execute($scopeParams);$registrations=$regStmt->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf(); $action=$_POST['action']??''; $reg=(int)($_POST['registration_id']??0);
 try {
  $q=$pdo->prepare("SELECT r.id FROM registrations r WHERE r.id=? AND ($scope) AND ($igdGuard)");$q->execute(array_merge([$reg],$scopeParams));if(!$q->fetchColumn())throw new RuntimeException('Kunjungan IGD tidak aktif atau di luar kewenangan.');
  if($user['role_code']==='admin_simrs' && $action==='upload'){
   $desc=trim($_POST['description']??'');$file=$_FILES['attachment']??null;
   if(!$desc||!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>10*1024*1024)throw new RuntimeException('Isi keterangan dan pilih berkas maksimal 10 MB.');
   $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'];if(!isset($allowed[$mime]))throw new RuntimeException('Hanya PDF, JPG, dan PNG yang diizinkan.');
   $dir=__DIR__.'/private_uploads';if(!is_dir($dir))mkdir($dir,0700,true);$stored=bin2hex(random_bytes(20)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('Gagal menyimpan berkas.');
   $pdo->prepare('INSERT INTO emr_attachments(registration_id,description,stored_name,original_name,mime_type,uploaded_by) VALUES(?,?,?,?,?,?)')->execute([$reg,$desc,$stored,basename($file['name']),$mime,$user['employee_id']]);
   flash('success','Scan berkas pasien IGD berhasil diunggah.');
  } elseif($user['role_code']==='igd' && $action==='vitals'){
   $urgency=$_POST['urgency']??'Kuning';$allowedUrgency=['Merah','Kuning','Hijau','Hitam'];if(!in_array($urgency,$allowedUrgency,true))throw new RuntimeException('Kategori triase tidak valid.');
   $pdo->prepare('INSERT INTO triage(registration_id,nurse_employee_id,urgency,bp,hr,rr,temp,spo2,notes,created_at) VALUES(?,?,?,?,?,?,?,?,?,NOW())')->execute([$reg,$user['employee_id'],$urgency,trim($_POST['bp']??''),trim($_POST['hr']??''),trim($_POST['rr']??''),trim($_POST['temp']??''),trim($_POST['spo2']??''),trim($_POST['notes']??'')]);
   flash('success','Tanda vital dan hasil triase berhasil disimpan.');
  } elseif($user['role_code']==='igd' && $action==='followup'){
   $note=trim($_POST['action_note']??'');if($note==='')throw new RuntimeException('Isi tindakan keperawatan yang telah dilakukan.');
   $pdo->prepare('INSERT INTO nursing_followups(registration_id,nurse_employee_id,action_note) VALUES(?,?,?)')->execute([$reg,$user['employee_id'],$note]);flash('success','Tindak lanjut keperawatan berhasil dicatat.');
  } else {http_response_code(403);exit('Aksi tidak sesuai kewenangan role.');}
 }catch(Throwable $e){flash('error',$e->getMessage());}
 redirect('triage.php');
}
$q=$pdo->prepare("SELECT t.*,r.registration_no,p.full_name,p.medical_record_no,e.full_name nurse_name FROM triage t JOIN registrations r ON r.id=t.registration_id JOIN patients p ON p.id=r.patient_id JOIN employees e ON e.id=t.nurse_employee_id WHERE ($scope) AND ($igdGuard) ORDER BY t.id DESC LIMIT 30");$q->execute($scopeParams);$history=$q->fetchAll();
$q=$pdo->prepare("SELECT nf.*,r.registration_no,p.full_name,e.full_name nurse_name FROM nursing_followups nf JOIN registrations r ON r.id=nf.registration_id JOIN patients p ON p.id=r.patient_id JOIN employees e ON e.id=nf.nurse_employee_id WHERE ($scope) AND ($igdGuard) ORDER BY nf.id DESC LIMIT 30");$q->execute($scopeParams);$followups=$q->fetchAll();
require __DIR__.'/includes/header.php'; ?>
<h1 class="page-title">IGD / Triase</h1><p class="page-subtitle">Pemisahan akses: perawat IGD mencatat tanda vital dan tindak lanjut keperawatan; administrator hanya mengunggah scan berkas pasien.</p>
<?php if($user['role_code']==='igd'): ?>
<div class="grid grid-2"><div class="card"><h2 class="section-title">Tanda-Tanda Vital dan Triase</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="vitals"><div class="field"><label>Pasien IGD</label><select class="input" name="registration_id" required><option value="">-- Pilih --</option><?php foreach($registrations as $r):?><option value="<?=$r['id']?>"><?=e($r['registration_no'].' · '.$r['medical_record_no'].' · '.$r['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Kategori Triase</label><select class="input" name="urgency"><option>Merah</option><option selected>Kuning</option><option>Hijau</option><option>Hitam</option></select></div><div class="grid grid-2"><div class="field"><label>TD (mmHg)</label><input class="input" name="bp"></div><div class="field"><label>HR (x/menit)</label><input class="input" name="hr"></div><div class="field"><label>RR (x/menit)</label><input class="input" name="rr"></div><div class="field"><label>Suhu (°C)</label><input class="input" name="temp"></div><div class="field"><label>SpO2 (%)</label><input class="input" name="spo2"></div></div><div class="field"><label>Catatan pengukuran</label><textarea class="input" name="notes" placeholder="Catatan tanda vital/observasi singkat"></textarea></div><button class="btn btn-primary">Simpan Tanda Vital</button></form></div>
<div class="card"><h2 class="section-title">Tindak Lanjut Keperawatan</h2><p class="note">Catat tindakan yang benar-benar dilakukan perawat, misalnya penggantian cairan/selang infus, pemantauan ulang tanda vital, perawatan luka, atau tindakan keperawatan lain sesuai instruksi dan SOP.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="followup"><div class="field"><label>Pasien IGD</label><select class="input" name="registration_id" required><option value="">-- Pilih --</option><?php foreach($registrations as $r):?><option value="<?=$r['id']?>"><?=e($r['registration_no'].' · '.$r['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Tindakan yang dilakukan</label><textarea class="input" name="action_note" required placeholder="Contoh: mengganti cairan infus sesuai instruksi dokter, pukul 14.30"></textarea></div><button class="btn btn-primary">Simpan Tindak Lanjut</button></form></div></div>
<?php else: ?><div class="card"><h2 class="section-title">Unggah Scan Berkas Pasien IGD</h2><p class="note">Administrator tidak dapat mengubah kategori triase, tanda vital, atau catatan klinis. Hanya unggah PDF/JPG/PNG maksimal 10 MB.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="upload"><div class="field"><label>Pasien IGD</label><select class="input" name="registration_id" required><option value="">-- Pilih --</option><?php foreach($registrations as $r):?><option value="<?=$r['id']?>"><?=e($r['registration_no'].' · '.$r['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Keterangan berkas</label><input class="input" name="description" required placeholder="Contoh: scan surat rujukan"></div><div class="field"><label>File</label><input class="input" type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png" required></div><button class="btn btn-primary">Unggah Berkas</button></form></div><?php endif; ?>
<div class="card" style="margin-top:18px"><h2 class="section-title">Riwayat Tanda Vital</h2><div class="table-wrap"><table><thead><tr><th>Pasien</th><th>Triase / Tanda Vital</th><th>Petugas</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e($h['full_name'])?><small><?=e($h['registration_no'].' · '.$h['medical_record_no'])?></small></td><td><?=e($h['urgency'])?><small>TD <?=e($h['bp'])?> · HR <?=e($h['hr'])?> · RR <?=e($h['rr'])?> · Suhu <?=e($h['temp'])?> · SpO2 <?=e($h['spo2'])?></small></td><td><?=e($h['nurse_name'])?></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="3">Belum ada data triase.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card" style="margin-top:18px"><h2 class="section-title">Riwayat Tindak Lanjut Keperawatan</h2><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Pasien</th><th>Tindakan</th><th>Perawat</th></tr></thead><tbody><?php foreach($followups as $f):?><tr><td><?=e($f['performed_at'])?></td><td><?=e($f['full_name'])?><small><?=e($f['registration_no'])?></small></td><td><?=nl2br(e($f['action_note']))?></td><td><?=e($f['nurse_name'])?></td></tr><?php endforeach;?><?php if(!$followups):?><tr><td colspan="4">Belum ada tindak lanjut.</td></tr><?php endif;?></tbody></table></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
